import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { ApiService } from "../../services/apiService";
import {
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  CircularProgress,
  Box,
  Chip,
  Fab,
  Autocomplete,
  Tooltip,
  useMediaQuery,
  useTheme,
  createFilterOptions,
  type FilterOptionsState,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import { useVillage } from "../hooks/useVillage";
import { useAuth } from "../hooks/useAuth";
import { useLoginModal } from "../context/LoginModalContext";
import { useAppDispatch, useAppSelector } from "../../store/hooks";
import {
  fetchAllSubCastes,
  fetchCastes,
  selectCastes,
  selectSubCastes,
} from "../../store/slices/casteSlice";

interface AddTreeProps {
  onCreate?: (treeId: string) => void;
  variant?: "button" | "fab";
}

type LookupOption = {
  id: string;
  name: string;
  casteId?: string;
};

type CreateOption = {
  id: string;
  name: string;
  inputValue: string;
  isCreateOption: true;
};

type AutocompleteOption = LookupOption | CreateOption;

const filter = createFilterOptions<AutocompleteOption>();

function isCreateOption(option: AutocompleteOption): option is CreateOption {
  return "isCreateOption" in option;
}

function renderLookupOption(
  props: React.HTMLAttributes<HTMLLIElement> & { key: React.Key },
  option: AutocompleteOption,
) {
  if (!isCreateOption(option)) {
    return <li {...props}>{option.name}</li>;
  }

  const { key, ...rest } = props;
  return (
    <Box
      component="li"
      key={key}
      {...rest}
      sx={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 1,
        px: 1.5,
        py: 1,
        borderLeft: "4px solid",
        borderColor: "success.main",
        bgcolor: "success.50",
        color: "success.dark",
      }}
    >
      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
        <AddCircleOutlineIcon fontSize="small" color="success" />
        <Box component="span" sx={{ fontWeight: 600 }}>
          {option.name}
        </Box>
      </Box>
      <Chip
        label="New"
        size="small"
        color="success"
        variant="filled"
        sx={{ fontWeight: 700 }}
      />
    </Box>
  );
}

export const AddTree: React.FC<AddTreeProps> = ({
  onCreate,
  variant = "button",
}) => {
  const dispatch = useAppDispatch();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));

  // Redux state
  const castes = useAppSelector(selectCastes);
  const subCastes = useAppSelector(selectSubCastes);

  // Local state
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [selectedCaste, setSelectedCaste] = useState<string>("");
  const [selectedSubCaste, setSelectedSubCaste] = useState<string>("");
  const [loading, setLoading] = useState(false);
  const [lookupLoading, setLookupLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [createdId, setCreatedId] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const modalHistoryRef = useRef(false);
  const [selectedVillageId, setSelectedVillageId] = useState<string>("");
  const [casteInputValue, setCasteInputValue] = useState("");
  const [subCasteInputValue, setSubCasteInputValue] = useState("");
  const filteredSubCastes = useMemo(
    () => subCastes.filter((s) => !selectedCaste || s.casteId === selectedCaste),
    [subCastes, selectedCaste],
  );
  const { villages, selectedVillage, setSelectedVillage } = useVillage();
  const { currentUser } = useAuth() as any;
  const { openLoginModal } = useLoginModal();

  // Load castes when modal opens
  useEffect(() => {
    if (showModal) {
      if (castes.length === 0) {
        dispatch(fetchCastes());
      }
      if (subCastes.length === 0) {
        dispatch(fetchAllSubCastes());
      }
    }
  }, [showModal, castes.length, subCastes.length, dispatch]);

  // Reset selected sub-caste when caste changes
  useEffect(() => {
    setSelectedSubCaste("");
    setSubCasteInputValue("");
  }, [selectedCaste]);

  const selectedCasteOption = useMemo(
    () => castes.find((caste) => caste.id === selectedCaste) || null,
    [castes, selectedCaste],
  );

  const selectedSubCasteOption = useMemo(
    () =>
      filteredSubCastes.find((subCaste) => subCaste.id === selectedSubCaste) || null,
    [filteredSubCastes, selectedSubCaste],
  );

  const createOptionLabel = (input: string, label: string) =>
    `Add "${input.trim()}" as new ${label}`;

  const buildCreatableOptions = useCallback(
    (
      options: LookupOption[],
      params: FilterOptionsState<AutocompleteOption>,
      label: string,
    ): AutocompleteOption[] => {
      const trimmedValue = params.inputValue.trim();
      const filtered = filter(options, params);

      if (!trimmedValue) {
        return filtered;
      }

      const hasExactMatch = options.some(
        (option) => option.name.trim().toLowerCase() === trimmedValue.toLowerCase(),
      );

      if (!hasExactMatch) {
        filtered.push({
          id: `create-${label}-${trimmedValue}`,
          name: createOptionLabel(trimmedValue, label),
          inputValue: trimmedValue,
          isCreateOption: true,
        });
      }

      return filtered;
    },
    [],
  );

  const handleCreateCaste = useCallback(
    async (nameToCreate: string) => {
      const trimmedName = nameToCreate.trim();
      if (!trimmedName) {
        return;
      }

      setError(null);
      setLookupLoading(true);
      try {
        const created = await ApiService.createCaste({ name: trimmedName });
        await dispatch(fetchCastes()).unwrap();
        setSelectedCaste(created.id);
        setCasteInputValue(created.name);
      } catch (err: any) {
        setError(err?.message ?? String(err));
      } finally {
        setLookupLoading(false);
      }
    },
    [dispatch],
  );

  const handleCreateSubCaste = useCallback(
    async (nameToCreate: string) => {
      const trimmedName = nameToCreate.trim();
      if (!trimmedName || !selectedCaste) {
        return;
      }

      setError(null);
      setLookupLoading(true);
      try {
        const created = await ApiService.createSubCaste({
          name: trimmedName,
          casteId: selectedCaste,
        });
        await dispatch(fetchAllSubCastes()).unwrap();
        setSelectedSubCaste(created.id);
        setSubCasteInputValue(created.name);
      } catch (err: any) {
        setError(err?.message ?? String(err));
      } finally {
        setLookupLoading(false);
      }
    },
    [dispatch, selectedCaste],
  );

  useEffect(() => {
    if (!showModal) return;

    if (!modalHistoryRef.current) {
      window.history.pushState({ modal: "create-tree" }, "");
      modalHistoryRef.current = true;
    }

    const handlePopState = () => {
      if (!modalHistoryRef.current) return;
      setShowModal(false);
      modalHistoryRef.current = false;
    };

    window.addEventListener("popstate", handlePopState);
    return () => {
      window.removeEventListener("popstate", handlePopState);
    };
  }, [showModal]);

  const submit = async () => {
    setError(null);
    setLoading(true);
    try {
      // Create tree and store caste/subCaste as UUIDs
      const treeData = {
        name: name || "Default Tree",
        villageId: selectedVillageId || selectedVillage || null,
        description: description || null,
        caste: selectedCaste || null,
        subCaste: selectedSubCaste || null,
      };

      const newTree = await ApiService.createTree(treeData);
      const treeId = newTree.id;

      setCreatedId(treeId);
      setName("");
      setDescription("");
      setSelectedCaste("");
      setSelectedSubCaste("");
      setShowModal(false);
      if (onCreate) onCreate(treeId);
    } catch (err: any) {
      setError(err?.message ?? String(err));
      console.error("Failed to create tree:", err);
    } finally {
      setLoading(false);
    }
  };

  const openModal = () => {
    if (!currentUser) {
      openLoginModal(() => {
        // After successful login, open the modal
        setShowModal(true);
      });
      return;
    }
    setError(null);
    setCreatedId(null);
    setName("");
    setDescription("");
    setSelectedCaste("");
    setSelectedSubCaste("");
    setCasteInputValue("");
    setSubCasteInputValue("");
    setSelectedVillageId(selectedVillage || "");
    setShowModal(true);
  };

  const closeModal = () => {
    if (loading) return;
    setShowModal(false);
    if (modalHistoryRef.current) {
      modalHistoryRef.current = false;
      window.history.back();
    }
  };

  const isValid =
    name.trim().length >= 4 &&
    name.trim().length <= 64 &&
    !!selectedCaste &&
    !!selectedSubCaste;

  return (
    <Box>
      {variant === "fab" ? (
        <>
          <Tooltip title="Create tree" placement="left">
            <Fab
              color="primary"
              aria-label="Create tree"
              onClick={openModal}
              sx={{
                display: { xs: "inline-flex", sm: "none" },
                opacity: 1,
                transition: "opacity 0.2s ease",
                "&:hover": {
                  opacity: 1,
                },
              }}
            >
              <AddIcon />
            </Fab>
          </Tooltip>
          <Tooltip title="Create tree" placement="left">
            <Fab
              variant="extended"
              color="primary"
              onClick={openModal}
              sx={{
                display: { xs: "none", sm: "inline-flex" },
                opacity: 0.62,
                transition: "opacity 0.2s ease",
                "&:hover": {
                  opacity: 1,
                },
              }}
            >
              <AddIcon sx={{ mr: 1 }} />
              Create tree
            </Fab>
          </Tooltip>
        </>
      ) : (
        <Button
          variant="contained"
          color="primary"
          startIcon={<AddIcon />}
          onClick={openModal}
        >
          Create tree
        </Button>
      )}

      <Dialog
        open={showModal}
        onClose={closeModal}
        maxWidth="sm"
        fullWidth
        fullScreen={isMobile}
      >
        <DialogTitle>Create a new tree</DialogTitle>
        <DialogContent>
          <Autocomplete
            options={villages}
            getOptionLabel={(option) => option.name}
            value={villages.find((v) => v.id === selectedVillageId) || null}
            onChange={(_e, newValue) => {
              const id = newValue?.id || "";
              setSelectedVillageId(id);
              if (id) {
                setSelectedVillage(id);
              }
            }}
            disabled={loading}
            renderInput={(params) => (
              <TextField
                {...params}
                margin="dense"
                label="Village"
                placeholder="Search village..."
                variant="outlined"
              />
            )}
            sx={{ mt: 1, mb: 2 }}
          />

          <TextField
            autoFocus
            margin="dense"
            label="Tree name"
            placeholder="e.g. Sharma Family"
            fullWidth
            variant="outlined"
            value={name}
            onChange={(e) => setName(e.target.value)}
            disabled={loading}
            sx={{ mt: 1, mb: 2 }}
          />

          <Autocomplete
            options={castes}
            value={selectedCasteOption}
            inputValue={casteInputValue}
            onInputChange={(_event, newInputValue) => {
              setCasteInputValue(newInputValue);
            }}
            onChange={async (_event, newValue) => {
              if (!newValue) {
                setSelectedCaste("");
                setCasteInputValue("");
                return;
              }

              if (isCreateOption(newValue)) {
                await handleCreateCaste(newValue.inputValue);
                return;
              }

              setSelectedCaste(newValue.id);
              setCasteInputValue(newValue.name);
            }}
            disabled={loading || lookupLoading}
            selectOnFocus
            clearOnBlur
            handleHomeEndKeys
            getOptionLabel={(option) =>
              isCreateOption(option) ? option.name : option.name
            }
            isOptionEqualToValue={(option, value) => option.id === value.id}
            filterOptions={(options, params) =>
              buildCreatableOptions(options, params, "caste")
            }
            renderOption={renderLookupOption}
            renderInput={(params) => (
              <TextField
                {...params}
                margin="dense"
                label="Caste"
                placeholder="Search or create caste..."
                variant="outlined"
                required
              />
            )}
            sx={{ mb: 2 }}
          />

          <Autocomplete
            options={filteredSubCastes}
            value={selectedSubCasteOption}
            inputValue={subCasteInputValue}
            onInputChange={(_event, newInputValue) => {
              setSubCasteInputValue(newInputValue);
            }}
            onChange={async (_event, newValue) => {
              if (!newValue) {
                setSelectedSubCaste("");
                setSubCasteInputValue("");
                return;
              }

              if (isCreateOption(newValue)) {
                await handleCreateSubCaste(newValue.inputValue);
                return;
              }

              setSelectedSubCaste(newValue.id);
              setSubCasteInputValue(newValue.name);
            }}
            disabled={loading || lookupLoading || !selectedCaste}
            selectOnFocus
            clearOnBlur
            handleHomeEndKeys
            getOptionLabel={(option) =>
              isCreateOption(option) ? option.name : option.name
            }
            isOptionEqualToValue={(option, value) => option.id === value.id}
            filterOptions={(options, params) =>
              buildCreatableOptions(options, params, "sub-caste")
            }
            renderOption={renderLookupOption}
            renderInput={(params) => (
              <TextField
                {...params}
                margin="dense"
                label="Sub-Caste"
                placeholder={
                  selectedCaste
                    ? "Search or create sub-caste..."
                    : "Select caste first"
                }
                variant="outlined"
                required
              />
            )}
            sx={{ mb: 2 }}
          />

          <TextField
            margin="dense"
            label="Description (Optional)"
            placeholder="e.g. A detailed description about the family"
            fullWidth
            variant="outlined"
            multiline
            rows={3}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={loading}
            sx={{ mb: 2 }}
          />

          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              Error: {error}
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closeModal} disabled={loading}>
            Cancel
          </Button>
          <Button
            onClick={submit}
            disabled={!isValid || loading}
            variant="contained"
            startIcon={loading ? <CircularProgress size={20} /> : null}
          >
            {loading ? "Creating..." : "Create"}
          </Button>
        </DialogActions>
      </Dialog>

      {createdId && !showModal && (
        <Alert severity="success" sx={{ mt: 1 }}>
          Created: {createdId}
        </Alert>
      )}
      {error && !showModal && (
        <Alert severity="error" sx={{ mt: 1 }}>
          Error: {error}
        </Alert>
      )}
    </Box>
  );
};

export default AddTree;
